		let lambda2 = max(mid - radius, 0.1);
		let vmin = min(1024.0, min(uniforms.viewportWidth, uniforms.viewportHeight));
		let l1 = 2.0 * min(sqrt(2.0 * lambda1), vmin);
		let l2 = 2.0 * min(sqrt(2.0 * lambda2), vmin);
